// Generated by AI (UnitTest MCP)
import { execFileSync } from "node:child_process";
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import {
  auditBranches,
  classifyCommits,
  mergeIsFaithful,
  reviewingRef,
  splitByReview,
} from "../../../scripts/merge-audit.mjs";

const temporaryDirectories = [];
const gitRepositoryVariables = [
  "GIT_DIR",
  "GIT_WORK_TREE",
  "GIT_COMMON_DIR",
  "GIT_INDEX_FILE",
  "GIT_OBJECT_DIRECTORY",
  "GIT_ALTERNATE_OBJECT_DIRECTORIES",
];

const isolatedGitEnvironment = () => {
  const isolated = { ...process.env };
  for (const variable of gitRepositoryVariables) delete isolated[variable];
  return isolated;
};

afterEach(() => {
  for (const directory of temporaryDirectories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

const git = (cwd, args) =>
  execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    stdio: "pipe",
    env: isolatedGitEnvironment(),
  }).trim();

const commitFile = (repo, name, content, message) => {
  writeFileSync(join(repo, name), content);
  git(repo, ["add", "--", name]);
  git(repo, ["commit", "-m", message]);
};

/** A repository with `main` and a feature branch, mirroring the real shape. */
const sandbox = () => {
  const root = mkdtempSync(join(tmpdir(), "mindleak-merge-audit-"));
  temporaryDirectories.push(root);
  const repo = join(root, "repo");
  mkdirSync(repo);
  git(repo, ["init", "-b", "main"]);
  git(repo, ["config", "user.name", "Merge Audit Test"]);
  git(repo, ["config", "user.email", "merge-audit@example.invalid"]);
  commitFile(repo, "README.md", "initial\n", "initial");
  return { root, repo };
};

describe("merge-audit", () => {
  // The PR #37 shape: the branch was merged at an earlier commit, then written
  // to again. Both the pull request and the branch look healthy in isolation;
  // only the ancestry says otherwise.
  it("reports commits made after the branch was merged", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "feature"]);
    commitFile(repo, "a.txt", "a\n", "landed before the merge");

    // main takes the branch as it stood, and only then the branch moves on.
    git(repo, ["checkout", "main"]);
    git(repo, ["merge", "--no-ff", "--no-edit", "feature"]);
    git(repo, ["checkout", "feature"]);
    commitFile(repo, "b.txt", "b\n", "the commit that was left behind");

    const { missing } = classifyCommits(repo, "main", "feature");

    expect(missing).toHaveLength(1);
    expect(missing[0]).toMatch(/the commit that was left behind/);
  }, 30_000);

  // The ordinary case must be silent, or the audit becomes noise and stops
  // being read — which is the same as not having it.
  it("stays silent when the whole branch landed", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "feature"]);
    commitFile(repo, "a.txt", "a\n", "all of the work");
    git(repo, ["checkout", "main"]);
    git(repo, ["merge", "--no-ff", "--no-edit", "feature"]);

    expect(classifyCommits(repo, "main", "feature")).toEqual({
      missing: [],
      replaced: [],
    });
  }, 30_000);

  // The regression that made the audit unsatisfiable. A squash or rebase merge
  // lands every line under a new commit id, which ancestry cannot distinguish
  // from a branch that never merged at all. The audit then reported the work as
  // lost and asked for a follow-up pull request for changes already on main —
  // an instruction nobody can carry out. An audit with no green move available
  // gets switched off, taking the check that catches real loss with it.
  it("reports a squash-merged branch as landed, not as lost work", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "feature"]);
    commitFile(repo, "a.txt", "the whole feature\n", "feat: the whole feature");

    // The squash: main gains the same patch under a different commit id.
    git(repo, ["checkout", "main"]);
    commitFile(repo, "a.txt", "the whole feature\n", "feat: the whole feature (#1)");

    const { missing, replaced } = classifyCommits(repo, "main", "feature");

    expect(missing).toEqual([]);
    expect(replaced).toHaveLength(1);
    expect(replaced[0]).toMatch(/feat: the whole feature$/);
  }, 30_000);

  // Merging the base into a long-running branch carries no work of its own, so
  // reporting it as lost is noise — and it was noise that padded the real
  // report, listing a "Merge branch 'main' into ..." commit beside the one
  // genuine finding.
  it("does not report merging the base in as work left behind", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "long-running"]);
    commitFile(repo, "a.txt", "branch work\n", "feat: branch work");

    git(repo, ["checkout", "main"]);
    commitFile(repo, "elsewhere.txt", "main work\n", "chore: unrelated");

    git(repo, ["checkout", "long-running"]);
    git(repo, ["merge", "main", "--no-edit"]);

    const { missing, replaced } = classifyCommits(repo, "main", "long-running");

    expect(missing).toHaveLength(1);
    expect(missing[0]).toMatch(/branch work$/);
    expect([...missing, ...replaced].some((c) => c.startsWith("Merge "))).toBe(false);
  }, 30_000);

  // "We cannot tell" and "nothing was lost" are different answers. A branch
  // that is gone cannot be checked for commits pushed after it merged, and
  // reporting it as clean would be the audit itself lying — the exact failure
  // it exists to catch.
  it("reports a missing branch as unverifiable rather than clean", () => {
    const { repo } = sandbox();

    const [result] = auditBranches(repo, "main", [{ ref: "origin/never-existed" }]);

    expect(result.verifiable).toBe(false);
    expect(result.missing).toEqual([]);
    expect(result.replaced).toEqual([]);
  }, 30_000);

  // The PR #507 shape, and the reason this check exists. `gh pr update-branch`
  // produced a merge commit that reported clean while its tree kept only one
  // side, silently dropping the branch's contribution. Nothing else in the
  // system can see it: the pull request says merged, the branch still shows the
  // code, and CI was green on both. `git cherry` cannot see it either, because
  // the branch tip is an ancestor of the base by construction once it merges.
  it("detects a merge commit whose tree drops one side's work", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "dropped"]);
    commitFile(repo, "kept.txt", "k\n", "work the merge will drop");
    git(repo, ["checkout", "main"]);
    commitFile(repo, "other.txt", "o\n", "main moves on");

    git(repo, ["merge", "--no-ff", "--no-commit", "dropped"]);
    git(repo, ["rm", "--quiet", "-f", "--", "kept.txt"]);
    git(repo, ["commit", "-m", "Merge branch 'dropped'"]);
    const mergeCommit = git(repo, ["rev-parse", "HEAD"]);

    const verdict = mergeIsFaithful(repo, mergeCommit);

    expect(verdict.compared).toBe(true);
    expect(verdict.faithful).toBe(false);
    expect(verdict.expected).not.toBe(verdict.actual);
  }, 30_000);

  // The same check must stay quiet on an honest merge, or it is noise that
  // gets switched off. Measured over main's last 120 merges: 0 mismatches.
  it("accepts a merge commit that is the merge of its own parents", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "honest"]);
    commitFile(repo, "kept.txt", "k\n", "work that survives");
    git(repo, ["checkout", "main"]);
    commitFile(repo, "other.txt", "o\n", "main moves on");
    git(repo, ["merge", "--no-ff", "--no-edit", "honest"]);

    const verdict = mergeIsFaithful(repo, git(repo, ["rev-parse", "HEAD"]));

    expect(verdict.compared).toBe(true);
    expect(verdict.faithful).toBe(true);
  }, 30_000);

  // A merge commit survives its branch, so this half of the audit keeps working
  // after GitHub deletes the branch on merge — which is what blinds the
  // `git cherry` half, and was measured dropping 10 of 30 pull requests.
  it("checks the merge commit even when the branch is gone", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "deleted-after-merge"]);
    commitFile(repo, "kept.txt", "k\n", "work the merge will drop");
    git(repo, ["checkout", "main"]);
    commitFile(repo, "other.txt", "o\n", "main moves on");
    git(repo, ["merge", "--no-ff", "--no-commit", "deleted-after-merge"]);
    git(repo, ["rm", "--quiet", "-f", "--", "kept.txt"]);
    git(repo, ["commit", "-m", "Merge branch 'deleted-after-merge'"]);
    const mergeCommit = git(repo, ["rev-parse", "HEAD"]);
    git(repo, ["branch", "-D", "deleted-after-merge"]);

    const [result] = auditBranches(repo, "main", [{ ref: "deleted-after-merge", mergeCommit }]);

    expect(result.verifiable).toBe(false);
    expect(result.merge.compared).toBe(true);
    expect(result.merge.faithful).toBe(false);
  }, 30_000);

  // A squash or rebase merge has one parent, so there is no branch side to
  // compare against, and a human conflict resolution is *supposed* to differ
  // from the automatic merge. Both must read as "cannot tell", never as a
  // verdict — a check that reports on evidence it does not have is worse than
  // one that admits the gap.
  it("declines to judge a merge it cannot reconstruct", () => {
    const { repo } = sandbox();

    expect(mergeIsFaithful(repo, git(repo, ["rev-parse", "HEAD"])).compared).toBe(false);
    expect(mergeIsFaithful(repo, null).compared).toBe(false);
  }, 30_000);

  it("audits several branches independently", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "clean"]);
    commitFile(repo, "clean.txt", "c\n", "clean work");
    git(repo, ["checkout", "main"]);
    git(repo, ["merge", "--no-ff", "--no-edit", "clean"]);

    git(repo, ["checkout", "-b", "leaky", "main"]);
    commitFile(repo, "leaky.txt", "l\n", "stranded work");

    const results = auditBranches(repo, "main", [{ ref: "clean" }, { ref: "leaky" }]);

    expect(results[0].missing).toEqual([]);
    expect(results[1].missing).toHaveLength(1);
    expect(results[1].missing[0]).toMatch(/stranded work/);
  }, 30_000);

  // The false alarm that turned main red on 2026-07-30. A commit pushed onto a
  // branch after its pull request merged is not lost if an open pull request
  // still carries it — and telling the reader to "open a follow-up pull
  // request" is unactionable when that is exactly what already exists. An
  // audit nobody can satisfy gets switched off, taking the check that catches
  // genuinely stranded work with it.
  it("a commit an open pull request still carries is in review, not lost", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "merged-already"]);
    commitFile(repo, "a.txt", "a\n", "landed before the merge");
    git(repo, ["checkout", "main"]);
    git(repo, ["merge", "--no-ff", "--no-edit", "merged-already"]);

    // Pushed onto the merged branch afterwards, then carried by an open one.
    git(repo, ["checkout", "merged-already"]);
    commitFile(repo, "b.txt", "b\n", "the late commit");
    git(repo, ["checkout", "-b", "still-open"]);

    const { missing } = classifyCommits(repo, "main", "merged-already");
    expect(missing).toHaveLength(1);

    const { stranded, inReview } = splitByReview(repo, missing, ["still-open"]);

    expect(stranded).toEqual([]);
    expect(inReview).toHaveLength(1);
    expect(inReview[0].ref).toBe("still-open");
    expect(inReview[0].commit).toMatch(/the late commit/);
  }, 30_000);

  // The check must keep earning its place: making the false alarm quiet by
  // reporting nothing would delete the whole point.
  it("a commit no open pull request carries is still stranded", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "merged-already"]);
    commitFile(repo, "a.txt", "a\n", "landed before the merge");
    git(repo, ["checkout", "main"]);
    git(repo, ["merge", "--no-ff", "--no-edit", "merged-already"]);
    git(repo, ["checkout", "merged-already"]);
    commitFile(repo, "b.txt", "b\n", "nobody is carrying this");

    // An unrelated open branch that does not contain it.
    git(repo, ["checkout", "-b", "elsewhere", "main"]);

    const { missing } = classifyCommits(repo, "main", "merged-already");
    const { stranded, inReview } = splitByReview(repo, missing, ["elsewhere"]);

    expect(inReview).toEqual([]);
    expect(stranded).toHaveLength(1);
    expect(stranded[0]).toMatch(/nobody is carrying this/);
  }, 30_000);

  // Degrading to the noisier answer is correct; degrading to a clean bill of
  // health would let an unreachable `gh` silence the audit.
  it("with no open pull requests known, every missing commit is stranded", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "merged-already"]);
    commitFile(repo, "a.txt", "a\n", "landed before the merge");
    git(repo, ["checkout", "main"]);
    git(repo, ["merge", "--no-ff", "--no-edit", "merged-already"]);
    git(repo, ["checkout", "merged-already"]);
    commitFile(repo, "b.txt", "b\n", "unclassifiable");

    const { missing } = classifyCommits(repo, "main", "merged-already");
    const { stranded, inReview } = splitByReview(repo, missing, []);

    expect(inReview).toEqual([]);
    expect(stranded).toHaveLength(1);
  }, 30_000);

  it("reviewingRef names the carrying ref, and null when none carries it", () => {
    const { repo } = sandbox();
    git(repo, ["checkout", "-b", "carrier"]);
    commitFile(repo, "a.txt", "a\n", "the work");
    const sha = git(repo, ["rev-parse", "HEAD"]);
    git(repo, ["checkout", "-b", "bystander", "main"]);

    expect(reviewingRef(repo, sha, ["bystander", "carrier"])).toBe("carrier");
    expect(reviewingRef(repo, sha, ["bystander"])).toBeNull();
  }, 30_000);
});
